    private static object? DeserializeObject(ref MessagePackReader reader, global::System.Type type)
    {
        if (reader.TryReadNil())
        {
            return null;
        }

        if (type == typeof(string))
        {
            return reader.ReadString();
        }

        if (type == typeof(byte[]))
        {
            // Func-level blobs are MessagePack bin; the array-of-int form is
            // accepted leniently (it is the record-context shape of
            // `list<u8>`).
            if (reader.NextMessagePackType == MessagePackType.Array)
            {
                var count = reader.ReadArrayHeader();
                var array = new byte[count];
                for (var i = 0; i < count; i++)
                {
                    array[i] = reader.ReadByte();
                }

                return array;
            }

            var bytes = reader.ReadBytes();
            return bytes.HasValue ? global::System.Buffers.BuffersExtensions.ToArray(bytes.Value) : null;
        }

        if (type == typeof(bool))
        {
            return reader.ReadBoolean();
        }

        if (type == typeof(byte))
        {
            return reader.ReadByte();
        }

        if (type == typeof(sbyte))
        {
            return reader.ReadSByte();
        }

        if (type == typeof(short))
        {
            return reader.ReadInt16();
        }

        if (type == typeof(ushort))
        {
            return reader.ReadUInt16();
        }

        if (type == typeof(int))
        {
            return reader.ReadInt32();
        }

        if (type == typeof(uint))
        {
            return reader.ReadUInt32();
        }

        if (type == typeof(long))
        {
            return reader.ReadInt64();
        }

        if (type == typeof(ulong))
        {
            return reader.ReadUInt64();
        }

        if (type == typeof(float))
        {
            return reader.ReadSingle();
        }

        if (type == typeof(double))
        {
            return reader.ReadDouble();
        }

        if (type == typeof(char))
        {
            var text = reader.ReadString();
            if (text is { Length: 1 })
            {
                return text[0];
            }

            throw new global::System.IO.InvalidDataException(
                "MSSP expected a single-character string for a char value");
        }

        if (TryDeserializeDto(ref reader, type, out var dto))
        {
            return dto;
        }

        if (type.IsEnum)
        {
            var underlying = DeserializeObject(ref reader, global::System.Enum.GetUnderlyingType(type));
            return global::System.Enum.ToObject(type, underlying!);
        }

        if (type.IsArray)
        {
            var elementType = type.GetElementType()!;
            var count = reader.ReadArrayHeader();
            var array = global::System.Array.CreateInstance(elementType, (int)count);
            for (var i = 0; i < (int)count; i++)
            {
                array.SetValue(DeserializeObject(ref reader, elementType), i);
            }

            return array;
        }

        if (type.IsGenericType)
        {
            var definition = type.GetGenericTypeDefinition();
            if (definition == typeof(global::System.Collections.Generic.List<>))
            {
                var elementType = type.GenericTypeArguments[0];
                var count = reader.ReadArrayHeader();
                var list = (global::System.Collections.IList)global::System.Activator.CreateInstance(type, (int)count)!;
                for (var i = 0; i < (int)count; i++)
                {
                    list.Add(DeserializeObject(ref reader, elementType));
                }

                return list;
            }

            if (definition == typeof(global::System.Nullable<>))
            {
                return DeserializeObject(ref reader, type.GenericTypeArguments[0]);
            }

            if (definition == typeof(global::System.ValueTuple<,>) || definition == typeof(global::System.ValueTuple<,,>))
            {
                var elementTypes = type.GenericTypeArguments;
                var count = reader.ReadArrayHeader();
                if (count != elementTypes.Length)
                {
                    throw new global::System.IO.InvalidDataException(
                        $"MSSP expected MessagePack array of length {elementTypes.Length}, got {count}");
                }

                var items = new object?[elementTypes.Length];
                for (var i = 0; i < elementTypes.Length; i++)
                {
                    items[i] = DeserializeObject(ref reader, elementTypes[i]);
                }

                return global::System.Activator.CreateInstance(type, items)!;
            }
        }

        throw new global::System.NotSupportedException(
            $"UniCodec cannot deserialize type {type} without MessagePackSerializerOptions");
    }

    /// Writes a generated DTO with its own formatter; returns `false` when
